# Let's create test images with different potential triggers and see the predictions
# We'll test different patch types, sizes, and corners

def create_patch_image(base_img, patch_type='white', patch_size=3, corner='top-left'):
    """Create an image with a trigger patch"""
    img = base_img.clone()
    c, h, w = img.shape

    # Determine position (1 pixel in from corner)
    if corner == 'top-left':
        y_start, x_start = 1, 1
    elif corner == 'top-right':
        y_start, x_start = 1, w - patch_size - 1
    elif corner == 'bottom-left':
        y_start, x_start = h - patch_size - 1, 1
    elif corner == 'bottom-right':
        y_start, x_start = h - patch_size - 1, w - patch_size - 1

    # Create patch
    if patch_type == 'white':
        patch = torch.ones(3, patch_size, patch_size, dtype=torch.uint8) * 255
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, patch_size, patch_size, dtype=torch.uint8)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif patch_type == 'random':
        patch = torch.randint(0, 2, (3, patch_size, patch_size), dtype=torch.uint8) * 255

    img[:, y_start:y_start+patch_size, x_start:x_start+patch_size] = patch
    return img

